import { Text } from "@chakra-ui/react";
import { type NodeProps, Handle, Position } from "reactflow";
import { extractNodeLabel } from "../../utils";
import { type CanvasNodeData, NodeState } from "../../types";

export const StartNode = (props: NodeProps<CanvasNodeData>) => {
  const { data, isConnectable, sourcePosition } = props;
  const nodeState = data.nodeState;
  const isActive = nodeState === NodeState.Active;

  const sx = {
    bg: "cyan.solid",
    color: "cyan.contrast",
    borderRadius: "full",
    border: "none",
    borderColor: "transparent",
    px: "6",
    py: "2",
    pointerEvents: "all",
    height: "auto",
  };

  return (
    <>
      <Text textStyle="xs" tabIndex={0} css={sx} data-testid={isActive ? "node-selected" : "node"}>
        {extractNodeLabel(data)}
      </Text>
      <Handle
        type="source"
        position={sourcePosition || Position.Bottom}
        isConnectable={isConnectable}
        style={{
          bottom: 0,
        }}
      />
    </>
  );
};
